INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerkgerät Daten an alle Anschlüsse sendet?', 2, '[{"text": "Ja", "correct": true, "because": "Es verteilt Daten ungerichtet"}, {"text": "Nein", "correct": false, "because": "Nicht zielgerichtet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal unterscheidet ein einfaches Netzwerkgerät von einem Switch?', 3, '[{"text": "Keine MAC-Adress-Tabelle", "correct": true, "because": "Sendet an alle Ports"}, {"text": "Höhere Geschwindigkeit", "correct": false, "because": "Nicht zwangsläufig"}, {"text": "Kleinere Größe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Gerät zur Datenverteilung?', 5, '[{"text": "Broadcast an alle Ports", "correct": true, "because": "Keine Adressfilterung"}, {"text": "Einfache Verkabelung", "correct": true, "because": "Verbindet mehrere Geräte"}, {"text": "Datenpaketanalyse", "correct": false, "because": "Nicht intelligent"}, {"text": "Hohe Sicherheitsfilter", "correct": false, "because": "Keine Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es arbeitet auf Schicht 1. b) Es reduziert Netzwerkkollisionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kollisionen können zunehmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerkgerät einsetze?', 4, '[{"text": "Bandbreitenaufteilung", "correct": false, "because": "Wichtig für Leistung"}, {"text": "Anschlussanzahl", "correct": false, "because": "Bestimmt Kapazität"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Geräte heute überall genutzt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Switches sind moderner"}, {"text": "Ja", "correct": false, "because": "Veraltet in vielen Netzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Verteiler im Netzwerk?', 3, '[{"text": "Signalweiterleitung", "correct": true, "because": "Verteilt Daten an alle"}, {"text": "Datenfilterung", "correct": false, "because": "Keine Intelligenz"}, {"text": "Sicherheitsprüfung", "correct": false, "because": "Kein Feature"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein einfaches Netzwerkgerät?', 5, '[{"text": "Kollisionen", "correct": true, "because": "Alle Ports gleichzeitig aktiv"}, {"text": "Bandbreitenverlust", "correct": true, "because": "Keine gezielte Weiterleitung"}, {"text": "Hohe Kosten", "correct": false, "because": "Eher günstig"}, {"text": "Komplexe Einrichtung", "correct": false, "because": "Sehr einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) es auf Schicht 2 arbeitet und b) es Datenpakete priorisiert. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Schicht 1, keine Priorisierung"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Verteilergerät einzusetzen?', 4, '[{"text": "Netzwerkkabel", "correct": false, "because": "Verbindet Geräte"}, {"text": "Stromversorgung", "correct": false, "because": "Für Betrieb nötig"}, {"text": "Firewall-Software", "correct": true, "because": "Kein Sicherheitsfeature"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Verteiler dasselbe wie ein Switch?', 2, '[{"text": "Nein", "correct": true, "because": "Switch ist intelligenter"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein einfaches Netzwerkgerät?', 4, '[{"text": "Kostengünstig", "correct": true, "because": "Günstiger als Switch"}, {"text": "Einfache Installation", "correct": true, "because": "Plug-and-Play"}, {"text": "Hohe Effizienz", "correct": false, "because": "Kollisionen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es in großen Netzen ideal ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kollisionen stören"}, {"text": "Ja", "correct": false, "because": "Besser für kleine Netze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Verteiler im Netzwerk?', 3, '[{"text": "Mehrere Geräte verbinden", "correct": true, "because": "Erweitert Anschlüsse"}, {"text": "Daten gezielt leiten", "correct": false, "because": "Keine Filterung"}, {"text": "Sicherheit erhöhen", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es sendet Daten an alle Ports. b) Es ist für moderne Netze optimal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist veraltet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, wenn ich Kollisionen vermeiden will?', 4, '[{"text": "Switch verwenden", "correct": true, "because": "Zielgerichtete Weiterleitung"}, {"text": "Mehr Verteiler", "correct": false, "because": "Erhöht Kollisionen"}, {"text": "Langsamere Kabel", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Verteiler Datenpakete analysiert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Weiterleitung"}, {"text": "Ja", "correct": false, "because": "Keine Intelligenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Verteilergerät nützlich?', 5, '[{"text": "Einfachheit", "correct": true, "because": "Leicht einzurichten"}, {"text": "Kosteneffizienz", "correct": true, "because": "Günstige Lösung"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Kein Schutz"}, {"text": "Datenpriorierung", "correct": false, "because": "Nicht möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeitet es auf Schicht 3?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Schicht 1"}, {"text": "Ja", "correct": false, "because": "Keine Routing-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem einfachen Netzwerkgerät?', 4, '[{"text": "Kleines Heimnetzwerk", "correct": true, "because": "Einfach und günstig"}, {"text": "Großes Firmennetz", "correct": false, "because": "Kollisionen störend"}, {"text": "High-Speed-Datenbank", "correct": false, "because": "Braucht Effizienz"}]');
